INSERT INTO settings (key, value) VALUES ('home_intro', '"<p>La mission de Lingerie &amp; maillots Christine est d’accompagner les femmes dans le choix d’une lingerie adaptée grâce à un service personnalisé, empreint d’écoute, de bienveillance, d’empathie et de respect, afin de créer une expérience d’achat agréable. Nous offrons également un service-conseil professionnel en vêtements postopératoires, puisque l’équipe est dûment formée et certifiées par la marque Anita qui est reconnue pour son expertise dans ce domaine. Notre priorité est que chaque femme se sente belle et confiante, malgré les défis physiques et émotionnels.</p>\n<h2>De la lingerie pour toutes les tailles</h2>\n<p>Lingerie féminine pour toutes les tailles. Soutiens-gorges variés (avec ou sans armature) et petites culottes assorties. Marques telles que Anita, Rosa Faia, Montelle, Van De Velde, Prima Donna, Marie Jo et Fit Fully Yours. Nous prenons vos mesures dans le respect et la plus grande discrétion, ce qui vous assura ainsi un bon maintien et le plus grand confort.</p>\n<p>Maillots de bain pour tous les types de tailles aux tendances mode actuelles, et ce, aussi confortable et adaptés autant aux poitrines épanouies. De plus nous avons des nuisettes confortables de la maque Montelle, confort inégalé.</p>\n<p>Venez vivre une expérience de magasinage agréable!</p>"') ON CONFLICT (key) DO UPDATE SET value = excluded.value, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE settings.value IN ('""', 'null');
